/** 可用星级（升序）。出题时随机取一个星级当"目标星级"。 */
export const CAPTCHA_STARS = Object.freeze([...new Set(CAPTCHA_EGGS.map((e) => e.star))].sort())

/** 按星级取蛋池。 */
export function eggsOfStar(star) {
  return CAPTCHA_EGGS.filter((e) => e.star === star)
}
